{
  "title": "图书馆的秘密",
  "scene": "你是一名热爱阅读的高中生，正在学校的图书馆内寻找一本关于科幻的小说。图书馆里安静极了，只有翻书的声音和偶尔的脚踏在地毯上的轻微声响。这里的书籍按类别整齐排列，每一排书架上都标有醒目的标签。这时，你注意到书架之间有一扇不起眼的门，上面没有任何标识。",
  "goal": "发现图书馆的秘密门后的情景，找到隐藏的科幻小说。",
  "choices": [
    {
      "id": "A",
      "text": "小心翼翼地推开门，看看里面有什么。",
      "outcome": "门后面是一间小房间，里面放着几本看起来年代久远的书籍，最显眼的是一本封面破旧的科幻小说。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "先不去管它，继续浏览其他书架看看能不能找到想要的书。",
      "outcome": "经过几个小时的搜索，你在角落的书架上终于找到了那本你一直在寻找的科幻小说。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "好奇地按下门边的一个按钮，但发现门并没有打开。",
      "outcome": "你发现门上有一个小按钮，按下去后发出“咔嚓”一声，但门没有反应，看起来是要钥匙才行。",
      "result": "fail",
      "next": "bad_end"
    }
  ]
}
